export const createImportMappingProfileBodyNameMax = 80;export const createImportMappingProfileBodyMappingMaxOne = 80;

export const createImportMappingProfileBody = zod.object({
  "kind": zod.enum(['customers', 'stock', 'opening_balances', 'metals', 'purities', 'items', 'sub_items', 'designs', 'stones', 'stone_rates', 'making_wastage_rules', 'vendors', 'staff', 'counters', 'floors', 'trays', 'hsn_codes', 'payment_modes', 'bank_accounts', 'card_machines']).describe('The 981 kinds (+ floors, 986). Master kinds reference other masters by code (export ⇄ import round-trips) and need masters.<area>.manage. bank_accounts is listed by 981 but not importable (422 validation_failed: encrypted account numbers). 0.8.0: `stock` is the opening-stock import: tagged rows (one piece each) and loose rows (blank tag, item + purity + weights, pieces optional, optional counter/tray). platform.import.run plus inventory.tag.create; commit goes through the Inventory service (one lot per branch with entry_type opening; tag_no kept when the file has one, else assigned from the shop tag format; ledger movement opening, tag_id null for loose rows; optional received_on column). Platform never writes inventory tables itself.'),
  "name": zod.string().min(1).max(createImportMappingProfileBodyNameMax),
  "mapping": zod.record(zod.string(), zod.string().max(createImportMappingProfileBodyMappingMaxOne)).describe('template column → source header, e.g. {\"phone\": \"Mobile No\"}'),
  "options": zod.object({
  "date_format": zod.enum(['YYYY-MM-DD', 'DD-MM-YYYY', 'DD/MM/YYYY']).optional()
}).optional()
})

